def occupied(ts, start='2018-06-15'):
    # occupied hours approx 7-19, weekdays
    res=[]
    from datetime import datetime
    for t,v in sorted(vals.get(ts,{}).items()):
        dt=datetime.fromisoformat(t)
        if dt.hour>=8 and dt.hour<=17 and dt.weekday()<5 and dt.date().isoformat()>=start:
